import { useHistory } from 'react-router-dom';

function SiteLink({
  text,
  location,
  classNames,
}) {
  const history = useHistory();

  function goToPage(location) {
    if (location) {
      history.push(`${location}`);
    }
  }
  return (
    <span className={`site-link ${classNames}`}onClick={() => goToPage(location)}>
      &gt;&gt;{text}&lt;&lt;
    </span>
  );
}

export default SiteLink;