import { useReducer, useRef, useState } from 'react';
import { useHistory } from 'react-router-dom';
import DOMPurify from 'dompurify';
import { StyledHeader, StyledSubheader, StyledSubheader3 } from '../styled';
import { majorFactions, minorFactions, rumoredFactions } from './factionData';
import {
  filtersReducer,
  initialFilters,
} from '../shared/filtersReducer';
import FactionFilter from '../shared/FactionFilter';
import './factions.css';

function Faction(props) {
  const {id, name, subhead, src, description} = props.faction;
  const history = useHistory();
  function goToFaction(id) {
    if (id) {
      history.push(`/factions/${id}`);
    }
  }

  const sanitizedText = () => ({
    __html: DOMPurify.sanitize(description)
  })
  return (
    <section
      className={`faction-section ${id ? 'faction-record' : ''}`}
      onClick={() => goToFaction(id)}
    >
      <aside>
        <img src={src} alt={name}></img>
      </aside>
      <article>
        <StyledSubheader>{name}</StyledSubheader>
        <StyledSubheader3>{subhead}</StyledSubheader3>
        <p dangerouslySetInnerHTML={sanitizedText()} />
      </article>
    </section>
  );
}

function Factions() {
  const [filters, dispatch] = useReducer(filtersReducer, initialFilters);
  const [showFactions, setShowFactions] = useState(false);
  function toggleShowFactions() {
    setShowFactions(!showFactions);
  }
  let majorFactionsList = [...majorFactions];
  let minorFactionsList = [...minorFactions];
  let rumoredFactionsList = [...rumoredFactions];

  if (filters.factions.size) {
    majorFactionsList = majorFactionsList.filter((f) => {
      return f.factions.some((faction) => filters.factions.has(faction))
    });

    minorFactionsList = minorFactionsList.filter((f) => {
      return f.factions.some((faction) => filters.factions.has(faction))
    });


    rumoredFactionsList = rumoredFactionsList.filter((f) => {
      return f.factions.some((faction) => filters.factions.has(faction))
    });
  }

  const majorRef = useRef(null);
  const minorRef = useRef(null);
  const rumoredRef = useRef(null);

  const barHeight = '50px';
  function scrollRefWithOffset(scrollRef) {
    scrollRef.current.style.scrollMargin = barHeight;
    scrollRef.current.scrollIntoView({ behavior: 'smooth' });
  }

  return (
    <>
      <nav className="sub-nav">
        <ul className="navigation">
          <li onClick={() => scrollRefWithOffset(majorRef)}>Major Factions</li>
          <li onClick={() => scrollRefWithOffset(minorRef)}>Minor Factions</li>
          <li onClick={() => scrollRefWithOffset(rumoredRef)}>Rumored Factions</li>
        </ul>
      </nav>

      <FactionFilter
        filters={filters}
        dispatch={dispatch}
        showFactions={showFactions}
        toggleShowFactions={toggleShowFactions}
        results={majorFactionsList.length + minorFactionsList.length + rumoredFactionsList.length}
      />
      
      <StyledHeader ref={majorRef}>Major Factions</StyledHeader>
      <ul>
        {majorFactionsList.map(function (faction, index) {
          return (
            <li key={`fact-major-${index}`}>
              <Faction faction={faction} />
            </li>
          );
        })}
      </ul>

      <StyledHeader style={{paddingTop: '1rem'}} ref={minorRef}>Minor Factions</StyledHeader>
      <ul>
        {minorFactionsList.map(function (faction, index) {
          return (
            <li key={`fact-minor-${index}`}>
              <Faction faction={faction} />
            </li>
          );
        })}
      </ul>

      <StyledHeader style={{ paddingTop: '1rem' }} ref={rumoredRef}>
        Rumored Factions
      </StyledHeader>
      <ul>
        {rumoredFactionsList.map(function (faction, index) {
          return (
            <li key={`fact-rumor-${index}`}>
              <Faction faction={faction} />
            </li>
          );
        })}
      </ul>
    </>
  );
}

export default Factions;